    extractMinIntervalDescription: 'Khoảng cách tối thiểu giữa hai lần chắt lọc cho cùng một người, dùng để giới hạn chi phí. Tin nhắn phát sinh trong khoảng này không bị bỏ qua — chúng được chuyển sang lần chạy tiếp theo.',
    vectorRecallLabel: 'Khớp bộ nhớ theo ngữ nghĩa',
    vectorRecallDescription: 'Bổ sung khớp ngữ nghĩa bên cạnh khớp theo câu chữ, để bộ nhớ vẫn được gợi lại khi người dùng diễn đạt chủ đề theo cách khác — và phần lớn bộ nhớ rồi sẽ được diễn đạt lại. Tốn một lời gọi embedding mỗi lượt, và quay về chỉ khớp theo câu chữ khi hết thời gian chờ (timeout).',
    embeddingModelLabel: 'Embedding model cho bộ nhớ',
    embeddingModelDescription: 'Gợi lại theo ngữ nghĩa dùng duy nhất model này, độc lập với các embedding model mà knowledge base gắn với. Để trống để chỉ khớp theo câu chữ. Sau khi thay đổi, bộ nhớ mới dùng model mới ngay; bộ nhớ hiện có vẫn chỉ khớp theo câu chữ cho đến khi được embedding lại.',
    conditioningLabel: 'Cho bộ nhớ định hướng truy xuất',
